import React from 'react';
import ListDropDown from '../../Common/ListDropDown';

const SchoolList = ({ schoolItem, fetchSchool, deleteSchool }) => {
  return (
    <tr>
      <td>{schoolItem.schoolCode}</td>
      <td>{schoolItem.schoolName}</td>
      <td>{schoolItem.address}</td>
      <td>{schoolItem.phoneNumber}</td>
      <td>{schoolItem.country}</td>
      <td>{schoolItem.currencyType}</td>
      <td className="text-center">
        <ListDropDown
          actionList={['edit', 'delete']}
          item={schoolItem}
          fetchItem={() => fetchSchool(schoolItem.schoolId)}
          deleteItem={() => deleteSchool(schoolItem.schoolId)}
        />
      </td>
    </tr>
  );
};

export default SchoolList;
