import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Input, Label, FormGroup, Row, Col } from 'reactstrap';
import validator from 'validator';
import Select from 'react-select';
import { languages } from '../../Guardian/components/GuardianFormModal';
import CustomButton from '../../../../components/CustomButton';
import { formResMessage } from 'utils/commonFunc';

export const currencyArr = [
  { label: 'Indian Rupee (₹)', value: 'INR' },
  { label: 'Dollar ($)', value: 'DOLLAR' },
];

const stateObj = {
  data: {
    // "schoolId": null,
    schoolCode: '',
    schoolName: '',
    address: '',
    mobileNumber: '',
    phoneNumber: '',
    country: 'India',
    currencyType: 'INR',
    language: 'EN',
    faxNumber: '',
    schoolShortName: '',
  },
  errors: {},
  loading: false,
};

class SchoolFormModal extends React.Component {
  state = stateObj;

  componentDidUpdate(prevProps) {
    if (prevProps.school !== this.props.school) {
      this.updateSchoolState(this.props.school);
    }
  }

  updateSchoolState = school => {
    this.setState(prevState => ({
      data: {
        ...prevState.data,
        schoolId: school.schoolId,
        schoolCode: school.schoolCode,
        schoolName: school.schoolName,
        address: school.address,
        mobileNumber: school.mobileNumber,
        phoneNumber: school.phoneNumber,
        country: school.country,
        currencyType: school.currencyType,
        language: school.language,
        faxNumber: school.faxNumber,
        schoolShortName: school.schoolShortName,
      },
    }));
  };

  handleChange = e => {
    const { name } = e.currentTarget;
    const { value } = e.currentTarget;
    if ((name === 'mobileNumber' && !isNaN(value)) || name !== 'mobileNumber') {
      this.setState({
        data: { ...this.state.data, [name]: value },
      });
    }
  };

  handleSelectChange = (name, selectItem) => {
    this.setState({
      data: {
        ...this.state.data,
        [name]: selectItem.value,
      },
    });
  };

  handleSubmit = e => {
    e.preventDefault();
    const { data } = this.state;
    const errors = this.validate(data);
    this.setState({ errors });
    if (Object.keys(errors).length === 0) {
      this.setState({ loading: true });
      data.phoneNumber = data.mobileNumber;
      if (data.schoolId) {
        this.props
          .updateSchool(data)
          .then(() => {
            this.stateReset();
            this.props.schoolUpdateSuccess('update');
          })
          .catch(err => this.setError(err));
      } else {
        this.props
          .saveSchool(data)
          .then(() => {
            this.stateReset();
            this.props.schoolUpdateSuccess('add');
          })
          .catch(err => this.setError(err));
      }
    }
  };

  setError = err => {
    this.setState({
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    });
  };

  stateReset = () => {
    this.setState(stateObj);
  };

  formModalClose = () => {
    this.stateReset();
    this.props.formModalClose();
  };

  validate = data => {
    const errors = {};
    if (validator.isEmpty(data.schoolCode.toString().trim())) {
      errors.schoolCode = 'School code cannot be empty';
    }
    if (validator.isEmpty(data.schoolName)) {
      errors.schoolName = 'School name cannot be empty';
    }
    if (!data?.schoolShortName) {
      errors.schoolShortName = 'School short name cannot be empty';
    }
    if (validator.isEmpty(data.address)) {
      errors.address = 'Address cannot be empty';
    }
    if (validator.isEmpty(data.mobileNumber.toString().trim())) {
      errors.mobileNumber = 'Mobile number cannot be empty';
    }
    if (validator.isEmpty(data.country)) {
      errors.country = 'Country cannot be empty';
    }
    if (validator.isEmpty(data.currencyType)) {
      errors.currencyType = 'Currency type cannot be empty';
    }
    return errors;
  };

  render() {
    const { isModalOpen } = this.props;
    const { data, errors, loading } = this.state;

    const thisData = (
      <Modal size="lg" isOpen={isModalOpen}>
        <form onSubmit={this.handleSubmit}>
          <ModalHeader>{data.id ? 'UPDATE SCHOOL' : 'ADD SCHOOL'}</ModalHeader>
          <ModalBody>
            {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
            <div className="content">
              <div className="container-fluid">
                <Row>
                  <Col sm={6} md={6}>
                    <FormGroup>
                      <Label htmlFor="">
                        School name<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="schoolName"
                        onChange={this.handleChange}
                        value={data.schoolName}
                        placeholder="Enter here..."
                        maxLength="50"
                      />
                      {errors.schoolName && <span className="err-msg">{errors.schoolName}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        School code<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="schoolCode"
                        onChange={this.handleChange}
                        value={data.schoolCode}
                        placeholder="Enter here..."
                        maxLength="20"
                      />
                      {errors.schoolCode && <span className="err-msg">{errors.schoolCode}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        School short name<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="schoolShortName"
                        onChange={this.handleChange}
                        value={data.schoolShortName}
                        placeholder="Enter here..."
                        maxLength="20"
                      />
                      {errors.schoolShortName && <span className="err-msg">{errors.schoolShortName}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Address<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="address"
                        onChange={this.handleChange}
                        value={data.address}
                        placeholder="Enter here..."
                        maxLength="100"
                      />
                      {errors.address && <span className="err-msg">{errors.address}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Mobile<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="mobileNumber"
                        onChange={this.handleChange}
                        value={data.mobileNumber}
                        placeholder="Enter here..."
                        maxLength="13"
                      />
                      {errors.mobileNumber && <span className="err-msg">{errors.mobileNumber}</span>}
                    </FormGroup>
                  </Col>
                  <Col sm={6} md={6}>
                    <FormGroup>
                      <Label htmlFor="">
                        Country<sup> *</sup>
                      </Label>
                      <Input
                        type="text"
                        name="country"
                        onChange={this.handleChange}
                        value={data.country}
                        placeholder="Enter here..."
                        maxLength="20"
                      />
                      {errors.country && <span className="err-msg">{errors.country}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Currency type<sup> *</sup>
                      </Label>
                      <Select
                        name="currencyType"
                        value={data.currencyType ? { label: data.currencyType, value: data.currencyType } : null}
                        onChange={value => this.handleSelectChange('currencyType', value)}
                        options={currencyArr}
                      />
                      {errors.currencyType && <span className="err-msg">{errors.currencyType}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">
                        Language <sup> *</sup>
                      </Label>
                      <Select
                        name="language"
                        value={data.language ? languages.find(dt => dt.value === data.language) : null}
                        onChange={value => this.handleSelectChange('language', value)}
                        options={languages}
                      />
                      {errors.language && <span className="err-msg">{errors.language}</span>}
                    </FormGroup>
                    <FormGroup>
                      <Label htmlFor="">Fax</Label>
                      <Input
                        type="text"
                        name="faxNumber"
                        onChange={this.handleChange}
                        value={data.faxNumber}
                        placeholder="Enter here..."
                        maxLength="15"
                      />
                    </FormGroup>
                  </Col>
                </Row>
              </div>
            </div>
          </ModalBody>
          <ModalFooter>
            <CustomButton
              type="submit"
              style={{ fontWeight: 'bold' }}
              variant="contained"
              color="secondary"
              disabled={loading}
              loading={loading}
            />
            <CustomButton
              className="ml-2"
              type="reset"
              style={{ fontWeight: 'bold' }}
              variant="contained"
              color="default"
              onClick={this.formModalClose}
              disabled={loading}
              name="Cancel"
            />
          </ModalFooter>
        </form>
      </Modal>
    );
    return <div>{thisData}</div>;
  }
}

export default SchoolFormModal;
