import React from 'react';
import { connect } from 'react-redux';
import { Card, CardBody, Table, Row, Col } from 'reactstrap';
import { schoolTableHead } from 'variables/general';

import {
  fetchAllSchoolsService,
  saveSchoolService,
  fetchSchoolService,
  updateSchoolService,
  deleteSchoolService,
} from 'actions/admin/schools';
import SchoolList from './components/SchoolList.jsx';
import SchoolFormModal from './components/SchoolFormModal.jsx';
import constants from '../../../config/constants.js';
import { logout, showToast } from '../../../actions/admin/auth.js';
import Page from '../Common/Pagination.jsx';
import { formResMessage, getGlobalSchoolUtils, getLoggedUserUtils } from '../../../utils/commonFunc.js';
import { store } from '../../../index.js';
import CustomButton from '../../../components/CustomButton.jsx';

class SchoolPage extends React.Component {
  constructor() {
    super();
    this.state = {
      isModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
    };
  }

  componentDidMount() {
    const userData = getLoggedUserUtils();
    const globalSchool = getGlobalSchoolUtils();
    if (userData?.userRole === constants.roles.SA) {
      this.fetchAllSchools();
    } else if (globalSchool?.schoolId) {
      this.initialFetchSchool();
    } else {
      this.showWarning('Sorry !!! You are not assigned to any school. Please contact School or Admin', 'warning');
    }
  }

  initialFetchSchool = () => {
    const globalSchool = getGlobalSchoolUtils();
    this.props.fetchSchool({
      schoolId: globalSchool.schoolId,
      token: this.props.loggedUserToken,
    });
  };

  formModalOpen = () => this.setState({ isModalOpen: true });

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  fetchAllSchools = () => {
    const { loggedUserId, loggedUserToken } = this.props;
    this.props.fetchAllSchools({
      adminId: loggedUserId,
      token: loggedUserToken,
      pageParams: this.state.pageParams,
    });
  };

  saveSchool = data => {
    const { loggedUserId, loggedUserToken } = this.props;
    return this.props.saveSchool({ postData: data, adminId: loggedUserId, token: loggedUserToken });
  };

  fetchSchool = schoolId => {
    return this.props.fetchSchool({ schoolId, token: this.props.loggedUserToken }).then(() => this.formModalOpen());
  };

  updateSchool = data => {
    return this.props.updateSchool({ schoolId: data.schoolId, postData: data, token: this.props.loggedUserToken });
  };

  schoolUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(actionParam === 'add' ? 'School added successfully' : 'School Updated successfully', 'success');
    if (this.props.loggedUserRole === constants.roles.SA) {
      this.fetchAllSchools();
    } else {
      this.initialFetchSchool();
    }
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  deleteSchool = schoolId => {
    if (this.props.loggedUserRole === constants.roles.SA) {
      this.deleteConfirm(schoolId);
    } else {
      this.showWarning('You are not authorized to delete school', 'error');
    }
  };

  deleteConfirm = schoolId => {
    return this.props
      .deleteSchool({ schoolId, token: this.props.loggedUserToken })
      .then(() => {
        this.fetchAllSchools();
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchPageData = page => {
    this.setState(
      {
        pageParams: {
          ...this.state.pageParams,
          page,
        },
      },
      () => {
        // window.scrosllTo(0, this.topRef.current.offsetTop)
        // let wHeight = window.innerHeight;
        // window.scrollY = wHeight;
        this.fetchAllSchools();
      }
    );
  };

  render() {
    const { isModalOpen } = this.state;
    const { loggedUserRole, schoolData, school } = this.props;
    if (loggedUserRole !== constants.roles.SA) {
      schoolData.content = [school];
    }
    const noDataFoundDiv = (
      <tr className="text-center">
        <td colSpan="8" style={{ paddingTop: 30, paddingBottom: 0, fontWeight: 'bold' }}>
          NO DATA FOUND
        </td>
      </tr>
    );
    return (
      <div className="content">
        <Row className="mb-3">
          {loggedUserRole === constants.roles.SA && (
            <Col>
              <CustomButton
                style={{ float: 'right', fontWeight: 'bold' }}
                variant="contained"
                color="secondary"
                onClick={this.formModalOpen}
                name="Add School"
              />
            </Col>
          )}
        </Row>
        <Row>
          <Col xs={12}>
            <Card>
              <CardBody>
                <Table size="sm" responsive>
                  <thead className="text-primary">
                    <tr>
                      {schoolTableHead.map((prop, key) => {
                        if (key === schoolTableHead.length - 1)
                          return (
                            <th key={key} className="text-center">
                              {prop}
                            </th>
                          );
                        return <th key={key}>{prop}</th>;
                      })}
                    </tr>
                  </thead>
                  <tbody>
                    {schoolData?.content?.length > 0
                      ? schoolData.content.map((schoolItem, i) => {
                          return (
                            <SchoolList
                              key={schoolItem.schoolId || i}
                              schoolItem={schoolItem}
                              fetchSchool={this.fetchSchool}
                              deleteSchool={this.deleteSchool}
                            />
                          );
                        })
                      : noDataFoundDiv}
                  </tbody>
                </Table>
                <hr />
                {loggedUserRole === constants.roles.SA && schoolData?.content?.length > 0 ? (
                  <Page {...schoolData} fetchPageData={this.fetchPageData} />
                ) : null}
              </CardBody>
            </Card>
          </Col>
        </Row>
        <SchoolFormModal
          isModalOpen={isModalOpen}
          formModalClose={this.formModalClose}
          saveSchool={this.saveSchool}
          school={school}
          updateSchool={this.updateSchool}
          schoolUpdateSuccess={this.schoolUpdateSuccess}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    schoolData: state.schools.schoolData,
    school: state.schools.school,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    logout: () => dispatch(logout()),
    fetchAllSchools: data => dispatch(fetchAllSchoolsService(data)),
    saveSchool: data => dispatch(saveSchoolService(data)),
    fetchSchool: data => dispatch(fetchSchoolService(data)),
    updateSchool: data => dispatch(updateSchoolService(data)),
    deleteSchool: data => dispatch(deleteSchoolService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(SchoolPage);
